(* ::Title:: Local P2 x C2: minimal genus <= 2 pipeline *)

(* ::Text:: Equivariant Gromov-Witten free energies F03, F04, F05 (genus 0, 3-5 points), F11 (genus 1) and F20 (genus 2) of K_P2 x C^2, extracted as the strict dependency chain from localp2final_CY5_v15.nb (the R-matrix coefficients cPP and the cyclic-projection table moncycproj are carried over as precomputed data; their derivations live in v15). Requires the sidecar file moncycproj.mx in the same directory. Evaluate linearly top to bottom. Approximate timings on the original machine: F03/F11 seconds-to-minutes, gr04[3] ~12 min, several gr05/gr20 terms take tens of minutes each (gr20 total is hours-scale). *)

(* ::Section:: Setup *)

(* ::Text:: Degree cutoff of the instanton expansion. *)

DMAX = 4; 

(* ::Text:: Replacement for Combinatorica Partitions[n,m] (partitions of n into parts <= m), used by ToSymPolLL below. v15 loaded the deprecated Combinatorica package for this single function. *)

Partitions[n_Integer, m_Integer] := IntegerPartitions[n, Infinity, Range[m]]

(* ::Text:: Chiral ring relation (p+a0)(p+a1)(p+a2)=0 for the torus weights a_i on P2, and the topological metric in terms of the elementary symmetric polynomials ee[i] of the weights; eps[1], eps[2] are the weights on the C^2 factor. *)

Replp3 = -Expand[(p + \[Alpha][0])*(p + \[Alpha][1])*(p + \[Alpha][2])] + p^3

\[Eta] = -{{-(1/(3*ee[3]*\[Epsilon][1]*\[Epsilon][2])), 0, 0}, {0, 0, 1/(3*\[Epsilon][1]*\[Epsilon][2])}, {0, 1/(3*\[Epsilon][1]*\[Epsilon][2]), -(ee[1]/(3*\[Epsilon][1]*\[Epsilon][2]))}}

e\[Alpha][i_] := SymmetricPolynomial[i, Table[\[Alpha][j], {j, 0, 2}]]

$Assumptions = {z > 0, Element[d, Integers], d >= 0}

(* ::Section:: The large-radius I-function and mirror map *)

(* ::Text:: Equivariant I-function of K_P2 (x C^2), its p^k z^-n coefficients II[k,n], the mirror map derivative C1 (closed hypergeometric form), L, and the inverse mirror map invmm. *)

ISummand[d_, z_] = z*Product[1/Product[p + \[Alpha][i] + m*z, {m, 1, d}], {i, 0, 2}]*Product[-3*p - m*z, {m, 0, 3*d - 1}]*y^d

IFun[y_] = FullSimplify[y^(p/z)*(z + Sum[ISummand[d, z], {d, 1, Infinity}])]

II[k_, n_] := Simplify[Coefficient[Collect[SeriesCoefficient[Series[IFun[y], {z, Infinity, 2}], n], p] /. p^3 -> Replp3, p, k]]

C1[y_] = FullSimplify[y*D[II[1, 0], y]]

L[y_] := (1/(1 + 27*y))^(1/3)

invmm = InverseSeries[Series[Exp[II[1, 0]], {y, 0, 4*DMAX}] /. y -> Q]

(* ::Text:: Zagier-Zinger relations (the only part of the v15 bigrepl needed downstream) and the cubic polPF whose roots are the canonical coordinates. *)

bigrepl = {cc2[y] -> ll[y]^3/c1[y]^2, dd2[y] -> (ee[1]/2)*(cc2[y] - ll[y]^3)}

polPF = Sum[ee[j]*XX[3 - j], {j, 1, 3}] + (1/ll[y]^3)*XX[3]

(* ::Section:: Canonical coordinates and Picard-Fuchs reduction machinery *)

(* ::Text:: Weight restriction as in the paper by Lho; the algebraic relation polPFLdiag for the canonical coordinates LLL[i][y] in the fibrewise specialisation a_i=(eps1+eps2)/3; reduction of rational functions and derivatives modulo that relation. *)

ee[0] = 1; ee[1] = ee[2]^2/3/ee[3]; 

polPFLdiag[y_, XX_] = Simplify[polPF /. XX[i_] -> XX^i /. ll -> L /. ee -> e\[Alpha] /. \[Alpha][ll_] -> \[Epsilon][1]/3 + \[Epsilon][2]/3]

