 0][P][x, y]*Derivative[1, 1][P][x, y]*Derivative[1, 2][P][x, y]*Derivative[4, 0][P][x, y] - 105*Derivative[0, 1][P][x, y]^4*Derivative[1, 0][P][x, y]^2*Derivative[1, 3][P][x, y]*Derivative[4, 0][P][x, y] + 105*Derivative[0, 1][P][x, y]^5*Derivative[1, 2][P][x, y]*Derivative[2, 0][P][x, y]*Derivative[4, 0][P][x, y] + 210*Derivative[0, 1][P][x, y]^5*Derivative[1, 1][P][x, y]*Derivative[2, 1][P][x, y]*Derivative[4, 0][P][x, y] + 105*Derivative[0, 1][P][x, y]^5*Derivative[1, 0][P][x, y]*Derivative[2, 2][P][x, y]*Derivative[4, 0][P][x, y] - 35*Derivative[0, 1][P][x, y]^6*Derivative[3, 1][P][x, y]*Derivative[4, 0][P][x, y] - 630*Derivative[0, 1][P][x, y]^4*Derivative[1, 0][P][x, y]*Derivative[1, 1][P][x, y]^2*Derivative[4, 1][P][x, y] - 315*Derivative[0, 1][P][x, y]^4*Derivative[1, 0][P][x, y]^2*Derivative[1, 2][P][x, y]*Derivative[4, 1][P][x, y] + 210*Derivative[0, 1][P][x, y]^5*Derivative[1, 1][P][x, y]*Derivative[2, 0][P][x, y]*Derivative[4, 1][P][x, y] + 210*Derivative[0, 1][P][x, y]^5*Derivative[1, 0][P][x, y]*Derivative[2, 1][P][x, y]*Derivative[4, 1][P][x, y] - 35*Derivative[0, 1][P][x, y]^6*Derivative[3, 0][P][x, y]*Derivative[4, 1][P][x, y] - 315*Derivative[0, 1][P][x, y]^4*Derivative[1, 0][P][x, y]^2*Derivative[1, 1][P][x, y]*Derivative[4, 2][P][x, y] + 105*Derivative[0, 1][P][x, y]^5*Derivative[1, 0][P][x, y]*Derivative[2, 0][P][x, y]*Derivative[4, 2][P][x, y] - 35*Derivative[0, 1][P][x, y]^4*Derivative[1, 0][P][x, y]^3*Derivative[4, 3][P][x, y] + 42*Derivative[0, 1][P][x, y]^5*Derivative[1, 1][P][x, y]^2*Derivative[5, 0][P][x, y] + 42*Derivative[0, 1][P][x, y]^5*Derivative[1, 0][P][x, y]*Derivative[1, 2][P][x, y]*Derivative[5, 0][P][x, y] - 21*Derivative[0, 1][P][x, y]^6*Derivative[2, 1][P][x, y]*Derivative[5, 0][P][x, y] + 84*Derivative[0, 1][P][x, y]^5*Derivative[1, 0][P][x, y]*Derivative[1, 1][P][x, y]*Derivative[5, 1][P][x, y] - 21*Derivative[0, 1][P][x, y]^6*Derivative[2, 0][P][x, y]*Derivative[5, 1][P][x, y] + 21*Derivative[0, 1][P][x, y]^5*Derivative[1, 0][P][x, y]^2*Derivative[5, 2][P][x, y] - 7*Derivative[0, 1][P][x, y]^6*Derivative[1, 1][P][x, y]*Derivative[6, 0][P][x, y] - 7*Derivative[0, 1][P][x, y]^6*Derivative[1, 0][P][x, y]*Derivative[6, 1][P][x, y] + Derivative[0, 1][P][x, y]^7*Derivative[7, 0][P][x, y]))))}; 

LLpowreddiag[exp_, var_] := Block[{temp = Together[exp]}, Factor[Collect[PolynomialRemainder[Numerator[temp], polPFLdiag[y, var], var], var]/Collect[PolynomialRemainder[Denominator[temp], polPFLdiag[y, var], var], var]]]

LLDerrepldiag = Simplify[Table[Derivative[l][LLL[i_]][y] -> LLpowreddiag[(ImplRepl[y, LLL[i][y]] /. P -> polPFLdiag)[[l]], LLL[i][y]], {l, 1, 3}]]; 

(* ::Text:: Cut-off in the z-expansion. *)

ZMAX = 3

(* ::Section:: The R-matrix *)

(* ::Text:: Closed forms of the R-matrix coefficients cPP[0,i][k] in the fibrewise limit, as derived in v15 (PF asymptotics + quantum Riemann-Roch normalisation + the delta->0 limit of the weight materialisation). The remaining rows PPdiag[1,.], PPdiag[2,.] follow from the flatness recursion; c1, c2, d2 are inert symbols at this stage. *)

cPP[0, i_][0] = Sqrt[3]/(Sqrt[(\[Epsilon][1]*\[Epsilon][2])/(\[Epsilon][1] + \[Epsilon][2])^3]*(\[Epsilon][1] + \[Epsilon][2])^2*(\[Epsilon][1] + \[Epsilon][2] + 3*LLL[0][y])) /. LLL[0][y] -> LLL[i][y]; 

cPP[0, i_][1] = ((1 + 27*y)*(\[Epsilon][1] + \[Epsilon][2] + 3*LLL[0][y])*((\[Epsilon][1] + \[Epsilon][2])*(\[Epsilon][1]^2 - 7*\[Epsilon][1]*\[Epsilon][2] + \[Epsilon][2]^2) + 3*(\[Epsilon][1]^2 - 11*\[Epsilon][1]*\[Epsilon][2] + \[Epsilon][2]^2)*LLL[0][y]))/(108*Sqrt[3]*y*((\[Epsilon][1]*\[Epsilon][2])/(\[Epsilon][1] + \[Epsilon][2])^3)^(3/2)*(\[Epsilon][1] + \[Epsilon][2])^7*((\[Epsilon][1] + \[Epsilon][2])^2 + 9*LLL[0][y]*(\[Epsilon][1] + \[Epsilon][2] + 3*LLL[0][y]))) /. LLL[0][y] -> LLL[i][y]; 

cPP[0, i_][2] = ((1 + 27*y)*((\[Epsilon][1] + \[Epsilon][2])^2*(8*\[Epsilon][1]*\[Epsilon][2]*(\[Epsilon][1]^2 - 27*\[Epsilon][1]*\[Epsilon][2] + \[Epsilon][2]^2) + 27*y*(\[Epsilon][1]^2 - 7*\[Epsilon][1]*\[Epsilon][2] + \[Epsilon][2]^2)^2) + 3*(\[Epsilon][1] + \[Epsilon][2])*(81*y*\[Epsilon][1]^4 + 2*(8 - 675*y)*\[Epsilon][1]^3*\[Epsilon][2] + (-496 + 8235*y)*\[Epsilon][1]^2*\[Epsilon][2]^2 + 2*(8 - 675*y)*\[Epsilon][1]*\[Epsilon][2]^3 + 81*y*\[Epsilon][2]^4)*LLL[0][y] + 9*(81*y*\[Epsilon][1]^4 + 2*(4 - 783*y)*\[Epsilon][1]^3*\[Epsilon][2] + (-280 + 14067*y)*\[Epsilon][1]^2*\[Epsilon][2]^2 + 2*(4 - 783*y)*\[Epsilon][1]*\[Epsilon][2]^3 + 81*y*\[Epsilon][2]^4)*LLL[0][y]^2))/(2592*Sqrt[3]*y*((\[Epsilon][1]*\[Epsilon][2])/(\[Epsilon][1] + \[Epsilon][2])^3)^(5/2)*(\[Epsilon][1] + \[Epsilon][2])^11*((-2 + 27*y)*(\[Epsilon][1] + \[Epsilon][2])^2 + 3*LLL[0][y]*((-5 + 108*y)*(\[Epsilon][1] + \[Epsilon][2]) + 9*(-1 + 54*y)*LLL[0][y]))) /. LLL[0][y] -> LLL[i][y]; 

cPP[0, i_][3] = -(((1 + 27*y)*((\[Epsilon][1]*\[Epsilon][2])/(\[Epsilon][1] + \[Epsilon][2])^3)^(3/2)*((\[Epsilon][1] + \[Epsilon][2])^2*(3753*y*(-2 + 27*y)*\[Epsilon][1]^6 + 81*y*(-418 + 4833*y)*\[Epsilon][1]^5*\[Epsilon][2] - 6*(160 + 729*y*(-58 + 53*y))*\[Epsilon][1]^4*\[Epsilon][2]^2 + (59200 - 81*y*(31586 + 85059*y))*\[Epsilon][1]^3*\[Epsilon][2]^3 - 6*(160 + 729*y*(-58 + 53*y))*\[Epsilon][1]^2*\[Epsilon][2]^4 + 81*y*(-418 + 4833*y)*\[Epsilon][1]*\[Epsilon][2]^5 + 3753*y*(-2 + 27*y)*\[Epsilon][2]^6) + 3*(\[Epsilon][1] + \[Epsilon][2])*(3753*y*(-5 + 108*y)*\[Epsilon][1]^6 + 81*y*(-1055 + 19872*y)*\[Epsilon][1]^5*\[Epsilon][2] - 6*(320 + 81*y*(-1475 + 5328*y))*\[Epsilon][1]^4*\[Epsilon][2]^2 + (127360 - 81*y*(112195 + 273816*y))*\[Epsilon][1]^3*\[Epsilon][2]^3 - 6*(320 + 81*y*(-1475 + 5328*y))*\[Epsilon][1]^2*\[Epsilon][2]^4 + 81*y*(-1055 + 19872*y)*\[Epsilon][1]*\[Epsilon][2]^5 + 3753*y*(-5 + 108*y)*\[Epsilon][2]^6)*LLL[0][y] + 27*(3753*y*(-1 + 54*y)*\[Epsilon][1]^6 + 243*y*(-73 + 3402*y)*\[Epsilon][1]^5*\[Epsilon][2] - 2*(160 + 27*y*(-3559 + 43686*y))*\[Epsilon][1]^4*\[Epsilon][2]^2 + (22720 + 27*y*(-119549 + 60426*y))*\[Epsilon][1]^3*\[Epsilon][2]^3 - 2*(160 + 27*y*(-3559 + 43686*y))*\[Epsilon][1]^2*\[Epsilon][2]^4 + 243*y*(-73 + 3402*y)*\[Epsilon][1]*\[Epsilon][2]^5 + 3753*y*(-1 + 54*y)*\[Epsilon][2]^6)*LLL[0][y]^2))/(466560*Sqrt[3]*y*\[Epsilon][1]^5*\[Epsilon][2]^5*((1 + 27*y*(-7 + 27*y))*(\[Epsilon][1] + \[Epsilon][2])^2 + 3*(2 + 135*y*(-4 + 27*y))*(\[Epsilon][1] + \[Epsilon][2])*LLL[0][y] + 9*(1 + 54*y*(-8 + 135*y))*LLL[0][y]^2))) /. LLL[0][y] -> LLL[i][y]; 

PPdiag[0, i_][z_] = Sum[cPP[0, i][k]*z^k, {k, 0, ZMAX}]; 

PPdiag[1, i_][z_] = Block[{arg = (LLL[i][y]*PPdiag[0, i][z] + z*y*D[PPdiag[0, i][z], y])/c1[y] /. LLDerrepldiag}, Sum[Simplify[LLpowreddiag[Coefficient[arg, z, k], LLL[i][y]]*z^k], {k, 0, ZMAX}]]; 

PPdiag[2, i_][z_] = Block[{arg = (LLL[i][y]*PPdiag[1, i][z] + z*y*D[PPdiag[1, i][z], y] - d2[y]*PPdiag[1, i][z])/c2[y] /. LLDerrepldiag}, Sum[Simplify[LLpowreddiag[Coefficient[arg, z, k], LLL[i][y]]*z^k], {k, 0, ZMAX}]]; 

(* ::Text:: The fibrewise limit of the weights, taken globally from here on. *)

\[Alpha][ll_] = (\[Epsilon][1] + \[Epsilon][2])/3; ee = e\[Alpha]; 

(* ::Section:: Dilaton leaves, marked leaves and edge terms *)

Do[Dilaton[i, n] = Coefficient[-PPdiag[0, i][-z], z, n - 1], {i, 0, 2}, {n, 1, ZMAX + 1}]

Do[Leaf[i, n, a] = Coefficient[PPdiag[a, i][-z] /. d2[y_] -> ee[1]*((1/2)*c2[y] - (1/2)*L[y]^3) /. c2[y] -> L[y]^3/c1[y]^2, z, n], {i, 0, 2}, {n, 0, ZMAX}, {a, 0, 2}]

Do[PreEdgeTerm[i, j] = KroneckerDelta[i, j] - Sum[PPdiag[a, i][-ww]*Inverse[\[Eta]][[a + 1,b + 1]]*PPdiag[b, j][-zz], {a, 0, 2}, {b, 0, 2}] /. d2[y_] -> ee[1]*((1/2)*c2[y] - (1/2)*L[y]^3) /. c2[y] -> L[y]^3/c1[y]^2 //. bigrepl /. LL[ll_] -> LLL[ll][y] /. ll -> L, {i, 0, 2}, {j, 0, 2}]; 

(* ::Text:: Divide id - P(-w)* P(-z) by (z+w) at the level of coefficients. This single loop covers all (i, j; m, n) needed below - including (i,j)=(1,1), which v15 computed in a session whose loop is not saved in the notebook. *)

Do[Block[{precoeff = CoefficientList[PreEdgeTerm[ij[[1]], ij[[2]]], {ww, zz}]}, Do[EdgeTerm[ij[[1]], ij[[2]], mn[[1]], mn[[2]]] = Together[Sum[(-1)^k*precoeff[[mn[[1]] + k + 2,mn[[2]] - k + 1]], {k, 0, mn[[2]]}]], {mn, {{0, 0}, {1, 0}, {2, 0}, {0, 1}, {1, 1}}}]], {ij, {{0, 0}, {0, 1}, {1, 1}}}]

(* ::Text:: Representing the terms used below in minimal form. *)

AbsoluteTiming[EdgeTerm[0, 0, 0, 0] = LLpowreddiag[EdgeTerm[0, 0, 0, 0], LLL[0][y]]; ]

AbsoluteTiming[EdgeTerm[0, 0, 1, 0] = LLpowreddiag[EdgeTerm[0, 0, 1, 0], LLL[0][y]]; ]

AbsoluteTiming[EdgeTerm[0, 0, 2, 0] = LLpowreddiag[EdgeTerm[0, 0, 2, 0], LLL[0][y]]; ]

AbsoluteTiming[EdgeTerm[0, 1, 0, 0] = LLpowreddiag[LLpowreddiag[EdgeTerm[0, 1, 0, 0], LLL[0][y]], LLL[1][y]]; ]

AbsoluteTiming[EdgeTerm[0, 1, 1, 0] = LLpowreddiag[LLpowreddiag[EdgeTerm[0, 1, 1, 0], LLL[0][y]], LLL[1][y]]; ]

AbsoluteTiming[EdgeTerm[1, 1, 0, 0] = LLpowreddiag[EdgeTerm[1, 1, 0, 0], LLL[1][y]]; ]

AbsoluteTiming[EdgeTerm[0, 0, 1, 1] = LLpowreddiag[EdgeTerm[0, 0, 1, 1], LLL[0][y]]; ]

AbsoluteTiming[EdgeTerm[0, 1, 1, 1] = LLpowreddiag[LLpowreddiag[EdgeTerm[0, 1, 1, 1], LLL[0][y]], LLL[1][y]]; ]

(* ::Text:: Square-lengths of the quantum idempotents. *)

sqrt\[CapitalDelta][i_] = Simplify[Sqrt[\[Epsilon][1]*(\[Epsilon][2]/ee[3])]*(3*ee[3] + ee[2]*LLL[i][y])]

(* ::Section:: Cyclic symmetrisation *)

(* ::Text:: ToSymPolLL rewrites a cyclically symmetric polynomial in the LLL[i][y] as an explicit function of y (the odd generator o = 3 Sqrt[3] I y (eps1+eps2)^3/(1+27y)^2 is hardcoded in its output). CyclicQuotOpt is the workhorse for graph contributions; moncycproj is its lookup table of cyclic projections of LLL-monomials up to total degree MONMAX, loaded from the sidecar moncycproj.mx (the commented-out cell regenerates it from scratch). WARNING: the degy/degDelta arguments of CyclicQuotOpt are trusted - underestimating them silently gives wrong results. *)

ToSymPolLL[arg_] := If[arg === 0, 0, Block[{argint = arg, par, exp, pol, sol, out, parodd, odd}, exp = Length[CoefficientList[argint, LLL[0][y]]] - 1; par = Select[Flatten[Table[Partitions[k, 3], {k, 0, 3*exp}], 1], Length[#1] <= exp & ]; parodd = Select[Flatten[Table[Partitions[k, 3], {k, 0, 3*(exp - 1)}], 1], Length[#1] <= exp - 2 & ]; odd = (LLL[0][y] - LLL[1][y])*(LLL[0][y] - LLL[2][y])*(LLL[1][y] - LLL[2][y]); pol = Sum[AA[k]*Product[SymmetricPolynomial[par[[k]][[j]], Table[LLL[i][y], {i, 0, 2}]], {j, 1, Length[par[[k]]]}], {k, 1, Length[par]}] + odd*Sum[AA[k + Length[par]]*Product[SymmetricPolynomial[parodd[[k]][[j]], Table[LLL[i][y], {i, 0, 2}]], {j, 1, Length[parodd[[k]]]}], {k, 1, Length[parodd]}]; sol = Flatten[Solve[CoefficientList[argint - pol, {LLL[0][y], LLL[1][y], LLL[2][y]}] == 0, Table[AA[k], {k, 1, Length[par] + Length[parodd]}]]]; If[sol == {}, Print["Error -- argument is not a cyclically symmetric polynomial in each LLL[i][y]"]; Abort[]]; out = Simplify[Sum[AA[k]*Product[(-1)^par[[k]][[j]]*e\[Alpha][par[[k]][[j]]]*L[y]^3, {j, 1, Length[par[[k]]]}], {k, 1, Length[par]}] + (3*Sqrt[3]*I*((y*(\[Epsilon][1] + \[Epsilon][2])^3)/(1 + 27*y)^2))*Sum[AA[Length[par] + k]*Product[(-1)^parodd[[k]][[j]]*e\[Alpha][parodd[[k]][[j]]]*L[y]^3, {j, 1, Length[parodd[[k]]]}], {k, 1, Length[parodd]}] /. sol]; out]]

MONMAX = 12

CyclicProj[arg_] := (1/3)*Sum[arg /. LLL[ll_][y] -> LLL[Mod[ll + kk, 3]][y], {kk, 1, 3}]

Null

SetDirectory[NotebookDirectory[]]; Get["moncycproj.mx"]; Dimensions[moncycproj]

CyclicQuotOpt[arg_, degy_, deg\[CapitalDelta]_] := Block[{num, den, denc, summand, sum, degLL}, num = Numerator[arg]; den = Denominator[arg]; denc = If[Head[den] == Times, Product[ToSymPolLL[Product[den[[m]] /. LLL[ll_] -> LLL[Mod[ll + kk, 3]], {kk, 0, 2}]], {m, 1, Length[den]}], ToSymPolLL[den]]; Print["Cyclic symmetrisation of the denominator OK. Result: "]; Print[denc]; summand = num*(den /. LLL[ll_][y] -> LLL[Mod[ll + 1, 3]][y])*(den /. LLL[ll_][y] -> LLL[Mod[ll + 2, 3]][y]); degLL = Max[Table[Exponent[summand, LLL[i][y]], {i, 0, 2}]]; Print[StringJoin["Max degree in LLL[i] is: ", ToString[degLL], "."]]; If[degLL > MONMAX, Print["Degree exceeds bounds. Try using a higher value for MONMAX. Aborting..."]; Abort[]]; Print["Starting cyclic symmetrisation of the numerator..."]; sum = Sum[Factor[Factor[Coefficient[Coefficient[Coefficient[(1 + 27*y)^deg\[CapitalDelta]*(summand/denc), LLL[2][y], m[2]], LLL[1][y], m[1]], LLL[0][y], m[0]]]*moncycproj[[m[0] + 1,m[1] + 1,m[2] + 1]]] /. Derivative[1][c1][y] -> cc1p /. c1[y] -> cc1, {m[0], 0, degLL}, {m[1], 0, degLL}, {m[2], 0, degLL}]; Print["Cyclic symmetrisation of the numerator OK. Interpolating..."]; Factor[InterpolatingPolynomial[Table[sum /. y -> n, {n, 1, degy + 1}], y]/(1 + 27*y)^deg\[CapitalDelta] /. cc1 -> c1[y] /. cc1p -> Derivative[1][c1][y]]]

(* ::Section:: Free energies: stable graph sums *)

(* ::Subsection:: g=0, n=3 *)

AbsoluteTiming[F03 = CyclicQuotOpt[3*Leaf[0, 0, 1]^3*sqrt\[CapitalDelta][0], 4, 1]]

F03Q = F03 /. c1 -> C1 /. y -> invmm

