gr11[2] = 3*(1/24)*CyclicQuotOpt[Dilaton[0, 2]*Leaf[0, 0, 1]*sqrt\[CapitalDelta][0]^2, 2, 1]

gr11[3] = 3*(1/2)*CyclicQuotOpt[EdgeTerm[0, 0, 0, 0]*Leaf[0, 0, 1]*sqrt\[CapitalDelta][0], 4, 1]

F11 = Simplify[Sum[gr11[k], {k, 1, 3}]]

F11Q = Simplify[Series[F11 /. c1 -> C1, {y, 0, 2*DMAX}] /. y -> invmm]

