gr04[1] = 3*(4/4!)*(CyclicQuotOpt[y*Leaf[0, 1, 1]*Leaf[0, 0, 1]^3*sqrt\[CapitalDelta][0]^2, 4, 2]/y)

gr04[2] = (3/4!)*(CyclicQuotOpt[y*Leaf[0, 0, 1]^4*sqrt\[CapitalDelta][0]^3*Dilaton[0, 2], 4, 2]/y)

AbsoluteTiming[gr04[3] = Block[{diag, offdiag}, diag = 3*(1/8)*CyclicQuotOpt[EdgeTerm[0, 0, 0, 0]*Leaf[0, 0, 1]^2*Leaf[0, 0, 1]^2*sqrt\[CapitalDelta][0]*sqrt\[CapitalDelta][0]*y, 8, 2]; offdiag = Coefficient[6*(1/8)*CyclicQuotOpt[EdgeTerm[0, 1, 0, 0]*Leaf[0, 0, 1]^2*Leaf[1, 0, 1]^2*sqrt\[CapitalDelta][0]*sqrt\[CapitalDelta][1]*y, 8, 2], Sqrt[3], 0]; Factor[Simplify[(diag + offdiag)/y]]]]

F04 = Simplify[gr04[1] + gr04[2] + gr04[3]]

F04Q = Simplify[4!*Series[Normal[Series[F04*\[Epsilon][1]*\[Epsilon][2] /. c1 -> C1, {y, 0, 2*DMAX}]] /. y -> invmm, {Q, 0, 2*DMAX}]]

