AbsoluteTiming[gr05[7] = Block[{diag, offdiag}, diag = 3*3*(1/2!/3!)*CyclicQuotOpt[EdgeTerm[0, 0, 0, 0]*Leaf[0, 0, 1]^2*Leaf[0, 0, 1]^2*Leaf[0, 1, 1]*sqrt\[CapitalDelta][0]*sqrt\[CapitalDelta][0]^2*y, 8, 3]; offdiag = Coefficient[6*3*(1/2!/3)*CyclicQuotOpt[EdgeTerm[0, 1, 0, 0]*Leaf[0, 0, 1]^2*Leaf[1, 0, 1]^2*Leaf[0, 1, 1]*sqrt\[CapitalDelta][0]^2*sqrt\[CapitalDelta][1]*y, 8, 3], Sqrt[3], 0]; Factor[Simplify[(diag + offdiag)/y]]]]

AbsoluteTiming[gr05[8] = Block[{diag, offdiag}, diag = 3*(1/2!/3!)*CyclicQuotOpt[EdgeTerm[0, 0, 0, 0]*Leaf[0, 0, 1]^2*Leaf[0, 0, 1]^3*Dilaton[0, 2]*sqrt\[CapitalDelta][0]*sqrt\[CapitalDelta][0]^3*y, 8, 3]; offdiag = Coefficient[6*(1/2!/3)*CyclicQuotOpt[EdgeTerm[0, 1, 0, 0]*Leaf[0, 0, 1]^2*Leaf[1, 0, 1]^2*Leaf[0, 0, 1]*Dilaton[0, 2]*sqrt\[CapitalDelta][0]^3*sqrt\[CapitalDelta][1]*y, 8, 3], Sqrt[3], 0]; Factor[Simplify[(diag + offdiag)/y]]]]

F05 = FullSimplify[5!*Sum[gr05[k], {k, 1, 8}]]

F05Q = FullSimplify[Series[Normal[Series[F05*\[Epsilon][1]*\[Epsilon][2] /. c1 -> C1, {y, 0, 2*DMAX}]] /. y -> invmm, {Q, 0, 2*DMAX}]]

