(* ::Text:: F20 in minimal form (XX = y c1p/c1, y in terms of LL), and its instanton expansion in the flat coordinate. *)

F20red = Collect[Expand[FullSimplify[F20/(\[Epsilon][1]*\[Epsilon][2]) /. Derivative[1][c1][y] -> (XX*c1[y])/y /. y -> (1 - LL^3)/(27*LL^3), LL > 0]], XX]

replxy = First[Solve[{xx == \[Epsilon][1] + \[Epsilon][2], yy == \[Epsilon][1]*\[Epsilon][2]}, {\[Epsilon][1], \[Epsilon][2]}]]

F20xy = Series[F20 /. replxy, {xx, 0, 8}, {yy, 0, 5}]

F20Q = Simplify[Simplify[Series[F20xy /. c1 -> C1, {y, 0, 2*DMAX}]] /. y -> invmm]
